{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "ALB listener uses unencrypted HTTP",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The listener accepts traffic over HTTP on port 80, so data between clients and the load balancer is transmitted without TLS encryption."
    },
    {
      "check_id": "CKV_AWS_103",
      "title": "ALB listener does not enforce TLS 1.2 or higher",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "Because the listener uses HTTP, it has no TLS policy and cannot enforce TLS 1.2 or higher."
    }
  ],
  "patched_code": "variable \"certificate_arn\" {\n  description = \"ARN of the ACM certificate used by the HTTPS listener\"\n  type        = string\n}\n\nresource \"aws_lb_listener\" \"webserver_listner\" {\n  load_balancer_arn = aws_lb.levelup-load-balancer.arn\n  port              = 443\n  protocol          = \"HTTPS\"\n  certificate_arn   = var.certificate_arn\n  ssl_policy        = \"ELBSecurityPolicy-TLS13-1-2-2021-06\"\n\n  default_action {\n    target_group_arn = aws_lb_target_group.load-balancer-target-group.arn\n    type             = \"forward\"\n  }\n}\n",
  "fix_summary": "Changed the listener from HTTP on port 80 to HTTPS on port 443, added an input for the ACM certificate ARN, and configured a security policy that permits only TLS 1.2 or newer."
}
